<script setup lang="ts">
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';
import Icon from '../components/Icon.vue';
import {api,get,message} from '../api';import {useAuth} from '../stores/auth';import PlanningMap from '../components/PlanningMap.vue';import PointPicker from '../components/PointPicker.vue';
const auth=useAuth(),route=useRoute(),router=useRouter(),options=ref<any>({nodes:[],grains:[]}),form=reactive<any>({}),source=ref<any>(null),run=ref<any>(null),loading=ref(false),solving=ref(false),publishing=ref(false),error=ref(''),preview=ref(''),segment=ref(0),detail=ref<any>(null),publishOpen=ref(false),supplierRows=ref<any[]>([]),supplierLoading=ref(false),supplierError=ref(''),selectedSupplyIds=ref<string[]>([]),publication=reactive({deadline:'',contact:'',phone:''}),publishError=ref('');
const keys=['grainId','quantity','origin','destination','departureAt','arrivalAt','modes','loadingType','containerType','containerCount','minBudget','maxBudget','notes'];const clean=ref('');const modeNames:Record<string,string>={ROAD:'公路',RAIL:'铁路',WATER:'水运'};
const active=computed(()=>run.value?.candidates.find((c:any)=>c.id===preview.value)||candidates.value[0]);const dirty=computed(()=>JSON.stringify(form)!==clean.value);const canPublish=computed(()=>auth.can('match:publish')&&auth.user?.businessEntity.type==='TRADER');
const candidates=computed(()=>{const choices=(run.value?.recommendedPlans||[]).map((r:any)=>({...run.value.candidates.find((c:any)=>c.id===r.candidateId),recommendationLabel:r.label,recommendationReasons:r.reasons})).filter((c:any)=>c.id);const selected=run.value?.candidates.find((c:any)=>c.id===run.value.selectedPlanId);if(selected&&!choices.some((c:any)=>c.id===selected.id))choices.push({...selected,recommendationLabel:'已选方案',recommendationReasons:[]});return choices;});
const activeRecommendation=computed(()=>candidates.value.find((c:any)=>c.id===active.value?.id));
const alternatives=computed(()=>run.value?.candidates.filter((c:any)=>!candidates.value.some((r:any)=>r.id===c.id))||[]);const intermodalCount=computed(()=>run.value?.candidates.filter((c:any)=>c.modes.length>1).length||0);const combinations=computed(()=>[...new Set(run.value?.candidates.filter((c:any)=>c.modes.length>1).map((c:any)=>c.familyLabel||c.modes.map((m:string)=>modeNames[m]).join(' + '))||[])]);
const departureClock=ref(new Date()),departureDefaultTime=ref(new Date(Date.now()+60000));let departureTimer:ReturnType<typeof setInterval>|undefined;const before=(n:number)=>Array.from({length:n},(_,i)=>i);const isToday=()=>!form.departureAt||new Date(form.departureAt).toDateString()===departureClock.value.toDateString();const departureHours=()=>isToday()?before(departureClock.value.getHours()):[];const departureMinutes=(h:number)=>isToday()&&h===departureClock.value.getHours()?before(departureClock.value.getMinutes()):[];const departureSeconds=(h:number,m:number)=>isToday()&&h===departureClock.value.getHours()&&m===departureClock.value.getMinutes()?before(departureClock.value.getSeconds()+1):[];function departureVisible(visible:boolean){clearInterval(departureTimer);departureClock.value=new Date();if(visible){departureDefaultTime.value=new Date(Date.now()+60000);departureTimer=setInterval(()=>departureClock.value=new Date(),1000);}}
const selectedSuppliers=computed(()=>supplierRows.value.filter(s=>selectedSupplyIds.value.includes(s.supplyId)));let supplierRequest=0;
async function loadSuppliers(){const sequence=++supplierRequest;supplierRows.value=[];selectedSupplyIds.value=[];supplierError.value='';if(!run.value||!active.value){supplierLoading.value=false;return;}supplierLoading.value=true;try{const data=await get('/plans/runs/'+run.value.id+'/suppliers',{candidateId:active.value.id});if(sequence===supplierRequest){supplierRows.value=data.items;if(run.value.publication&&active.value.id===run.value.selectedPlanId){const p=run.value.publication;const ids=p.recipients?.length?p.recipients.map((r:any)=>r.supplyId):[p.supplyId];selectedSupplyIds.value=data.items.filter((s:any)=>ids.includes(s.supplyId)).map((s:any)=>s.supplyId);}}}catch(e){if(sequence===supplierRequest)supplierError.value=message(e);}finally{if(sequence===supplierRequest)supplierLoading.value=false;}}
watch(()=>[run.value?.id,active.value?.id],loadSuppliers);
const money=(v:number|null)=>v==null?'待报价':'¥'+(v/100).toLocaleString('zh-CN',{maximumFractionDigits:2});const date=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';const hours=(v:number)=>v===0?'0小时':v>=86400?`${Math.floor(v/86400)}天${Math.round(v%86400/3600)}小时`:`${Math.max(1,Math.round(v/3600))}小时`;const unitCost=(v:number|null)=>v==null?'待报价':money(Math.round(v/(run.value?.input.quantity||form.quantity||1)))+'/吨';
function measure(value:any,minimumFractionDigits=0,maximumFractionDigits=minimumFractionDigits){if(value==null||value===''||!Number.isFinite(Number(value)))return '—';return Number(value).toLocaleString('zh-CN',{minimumFractionDigits,maximumFractionDigits});}
const feeUnits:Record<string,string>={'元/吨公里':'吨公里','元/吨':'吨','元/箱':'箱','元/单':'单'};
function feeQuantity(row:any){return measure(row.quantity,row.unit==='元/吨'?1:0,row.unit==='元/吨公里'?4:row.unit==='元/吨'?1:0);}
function feeBasis(row:any){if(row.unit!=='元/吨公里'||!run.value?.input||detail.value?.distanceMeters==null)return '';return `${measure(run.value.input.quantity,1)} 吨 × ${measure(detail.value.distanceMeters/1000,0,3)} 公里`;}
function blank(){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{grainId:'',quantity:null,origin:null,destination:null,departureAt:'',arrivalAt:'',modes:['ROAD','RAIL','WATER'],loadingType:'BULK',containerType:'20GP',containerCount:null,minBudget:null,maxBudget:null,notes:''});source.value=null;run.value=null;preview.value='';segment.value=0;clean.value=JSON.stringify(form);}
function apply(input:any){for(const key of keys)if(input[key]!==undefined)form[key]=JSON.parse(JSON.stringify(input[key]));clean.value=JSON.stringify(form);}
async function initialize(){if(solving.value)return;if(route.query.runId&&run.value?.id===route.query.runId)return;loading.value=true;error.value='';blank();try{options.value=await get('/plans/options');if(route.query.runId){run.value=await get('/plans/runs/'+route.query.runId);apply(run.value.input);source.value=run.value.demandId?{...run.value.input.sourceDemand,demandId:run.value.demandId,demandVersion:run.value.demandVersion,orderNo:run.value.input.sourceOrderNo}:null;preview.value=run.value.selectedPlanId||candidates.value[0]?.id||'';}else if(route.query.demandId){source.value=await get('/plans/demand/'+route.query.demandId+'/input');apply(source.value);if(!form.modes.length)form.modes=['ROAD','RAIL','WATER'];}clean.value=JSON.stringify(form);}catch(e){error.value=message(e);}finally{loading.value=false;}}
watch(()=>[route.query.demandId,route.query.runId],initialize,{immediate:true});
async function solve(){await nextTick();error.value='';const missing=[!form.grainId&&'粮食品种',!form.quantity&&'运输数量',!form.origin&&'起运位置',!form.destination&&'目的位置',!form.departureAt&&'计划发运时间',!form.arrivalAt&&'要求到达时间'].filter(Boolean);if(missing.length){error.value='请填写：'+missing.join('、');return;}if(new Date(form.departureAt).getTime()<=Date.now()){error.value='计划发运时间必须晚于当前时间';return;}if(new Date(form.arrivalAt)<=new Date(form.departureAt)){error.value='要求到达时间必须晚于计划发运时间';return;}if(form.minBudget!=null&&form.maxBudget!=null&&form.minBudget>form.maxBudget){error.value='总预算下限不能大于上限';return;}if([form.origin,form.destination].some(p=>p.matchKind==='APPROXIMATE')){error.value='地址仅定位到区域，请点击地址并在地图上确认实际装卸位置';return;}solving.value=true;try{const dto:any=Object.fromEntries(keys.filter(k=>form[k]!==''&&form[k]!=null).map(k=>[k,form[k]]));Object.assign(dto,{allowModel:true,allowMultimodal:source.value?.allowMultimodal??true,allowTransfer:source.value?.allowTransfer??true,maxTransfers:source.value?.maxTransfers??4,allowContainerization:true,preference:'BALANCED'});if(form.loadingType==='BULK'){delete dto.containerCount;delete dto.containerType;}if(source.value){dto.demandId=source.value.demandId;dto.demandVersion=source.value.demandVersion;}if(run.value)dto.previousRunId=run.value.id;run.value=(await api.post('/plans/solve',dto,{timeout:180000})).data.data;preview.value=candidates.value[0]?.id||'';segment.value=0;clean.value=JSON.stringify(form);await router.replace({query:{runId:run.value.id}});ElMessage.success(run.value.candidates.length?`已生成 ${run.value.recommendedPlans.length} 条推荐方案`:'没有满足条件的方案，请调整时间或地点');}catch(e){error.value=message(e);}finally{solving.value=false;}}
async function reset(){if(!await discard())return;blank();await router.replace({query:{}});}
async function showPublish(){if(!active.value||dirty.value)return;if(!selectedSuppliers.value.length){ElMessage.warning('请先选择物流供应商');return;}publishError.value='';if(!publication.deadline||new Date(publication.deadline)<=new Date())publication.deadline=new Date(Math.min(Date.now()+86400000,new Date(form.departureAt).getTime()-3600000)).toISOString();publication.contact||=auth.user?.displayName||'';publication.phone||=auth.user?.phone||auth.user?.businessEntity.phone||'';publishOpen.value=true;}
async function publish(){publishError.value='';if(!publication.deadline){publishError.value='请选择响应截止时间';return;}if(!selectedSuppliers.value.length){publishError.value='请先选择物流供应商';return;}if(!run.value.demandId&&(!publication.contact||!publication.phone)){publishError.value='请填写联系人和联系电话';return;}publishing.value=true;try{const dto:any={candidateId:active.value.id,revision:run.value.revision,deadline:publication.deadline,suppliers:selectedSuppliers.value.map(s=>({targetCarrierId:s.carrierId,supplyId:s.supplyId,supplyVersion:s.supplyVersion}))};if(!run.value.demandId)Object.assign(dto,{contact:publication.contact,phone:publication.phone});const result=(await api.post('/plans/runs/'+run.value.id+'/publish',dto)).data.data;publishOpen.value=false;clean.value=JSON.stringify(form);ElMessage.success('方案已发布，等待所选供应商报价');publishing.value=false;await router.push({path:'/matches',query:{id:result.id}});}catch(e){publishError.value=message(e);}finally{publishing.value=false;}}
async function discard(){if(solving.value||publishing.value)return false;if(dirty.value)try{await ElMessageBox.confirm('当前输入条件尚未求解，离开后将丢失。','离开求解页？',{confirmButtonText:'离开',cancelButtonText:'继续填写'});}catch{return false;}return true;}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(to=>to.query.runId===run.value?.id?true:discard());function unload(e:BeforeUnloadEvent){if(dirty.value||solving.value){e.preventDefault();e.returnValue='';}}onMounted(()=>window.addEventListener('beforeunload',unload));onBeforeUnmount(()=>{clearInterval(departureTimer);window.removeEventListener('beforeunload',unload);});
</script>
<template>
<el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="plan-alert"/>
<el-skeleton v-if="loading" :rows="8" animated/><div v-else class="planning-layout">
<section class="plan-input-panel">
<header class="conditions-heading"><div><Icon name="route" :size="20"/><h2>运输条件</h2><span>规划整单运输方案</span></div><span v-if="source" class="conditions-source"><Icon name="file" :size="14"/>{{source.businessNo||'已关联运输需求'}}</span></header>
<el-form label-position="top" class="plan-form" :disabled="solving" @submit.prevent="solve">
<div class="conditions-grid"><div class="conditions-section-label"><Icon name="map" :size="15"/>运输路线</div><el-form-item class="route-field" label="起运详细地址" required><PointPicker v-model="form.origin" label="起运位置" :nodes="options.nodes" :search-text="source?.originSearch" :disabled="solving"/></el-form-item><el-form-item class="route-field" label="目的详细地址" required><PointPicker v-model="form.destination" label="目的位置" :nodes="options.nodes" :search-text="source?.destinationSearch" :disabled="solving"/></el-form-item><div class="conditions-section-label"><Icon name="package" :size="15"/>货物与运输安排</div><el-form-item label="粮食品种" required><el-select v-model="form.grainId" :disabled="!!source" aria-label="粮食品种"><el-option v-for="g in options.grains" :key="g.id" :value="g.id" :label="g.label"/></el-select></el-form-item><el-form-item label="运输数量（吨）" required><el-input-number v-model="form.quantity" :disabled="!!source" :min=".1" :max="100000" :precision="1" :step=".1" :controls="false" aria-label="运输数量"/></el-form-item>
<el-form-item class="mode-field" label="运输方式偏好"><el-checkbox-group v-model="form.modes"><el-checkbox v-for="(label,value) in modeNames" :key="value" :value="value" :disabled="source?.modes?.length&&!source.modes.includes(value)">{{label}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item class="loading-field" label="装载形式"><el-select v-model="form.loadingType" :disabled="!!source" aria-label="装载形式"><el-option label="散货" value="BULK"/><el-option label="集装箱" value="CONTAINER"/></el-select></el-form-item><el-form-item class="time-field" label="计划发运时间" required><el-date-picker v-model="form.departureAt" :disabled="!!source" :disabled-date="(d:Date)=>d.getTime()<new Date(departureClock).setHours(0,0,0,0)" :disabled-hours="departureHours" :disabled-minutes="departureMinutes" :disabled-seconds="departureSeconds" :default-time="departureDefaultTime" :show-now="false" @visible-change="departureVisible" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择未来时间" aria-label="计划发运时间"/></el-form-item><el-form-item class="time-field" label="要求到达时间" required><el-date-picker v-model="form.arrivalAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择要求到达时间" aria-label="要求到达时间"/></el-form-item><div class="conditions-section-label budget-section"><Icon name="wallet" :size="15"/>总预算<span>选填 · 整单总价</span></div><el-form-item class="budget-field" label="总预算区间（元）"><div class="budget-range"><el-input-number v-model="form.minBudget" :min="0" :max="20000000" :precision="2" :step="1000" :controls="false" placeholder="最低总预算" aria-label="总预算下限（元）"/><span>至</span><el-input-number v-model="form.maxBudget" :min="0" :max="20000000" :precision="2" :step="1000" :controls="false" placeholder="最高总预算" aria-label="总预算上限（元）"/><span class="budget-unit">元</span></div><small class="budget-hint">按全程测算总费用筛选，留空表示不限；支持仅填写下限或上限。</small><small v-if="form.minBudget!=null&&form.maxBudget!=null&&form.minBudget>form.maxBudget" class="budget-error" role="alert">总预算下限不能大于上限</small></el-form-item><el-form-item class="notes-field" label="补充要求（选填）"><el-input v-model="form.notes" maxlength="2000" placeholder="填写装卸、时效或其他运输要求" aria-label="补充要求"/></el-form-item></div>
<div class="conditions-footer"><div class="supplement"><template v-if="form.loadingType==='CONTAINER'"><el-select v-model="form.containerType" aria-label="箱型"><el-option value="20GP" label="20GP"/><el-option value="40GP" label="40GP"/></el-select><el-input-number v-model="form.containerCount" :min="1" :max="10000" :controls="false" placeholder="箱数" aria-label="箱数"/></template></div><div class="query-actions"><el-button @click="reset">重置</el-button><el-button type="primary" :loading="solving" @click="solve">{{solving?'正在计算路线…':'开始求解'}}</el-button></div></div></el-form>
<div v-if="source&&(!form.origin||!form.destination||form.origin?.matchKind==='APPROXIMATE'||form.destination?.matchKind==='APPROXIMATE')" class="address-notice">原始需求地址已保留。未定位或仅定位到区域的地址，请点击核对实际装卸位置后求解。</div></section>
<section class="solution-workspace"><div class="map-area"><PlanningMap :segments="active?.segments||[]" :points="active?[]:[form.origin,form.destination].filter(Boolean)" :selected="segment" @select="segment=$event"/><div class="map-route-caption" v-if="active"><strong>{{form.origin?.name}} → {{form.destination?.name}}</strong><span>{{active.modes.map((m:string)=>modeNames[m]).join(' + ')}} · {{active.transferCount}}次衔接</span></div></div>
<aside class="solutions-panel"><div class="results-title"><strong>运输方案</strong><span>{{run?.recommendedPlans.length||0}} 条推荐方案</span></div>
<template v-if="candidates.length"><div class="recommendation-intro">已找到 {{intermodalCount}} 条联运路线<span v-if="intermodalCount">，优先在联运组合中推荐。</span><span v-else>，当前展示单方式备选。</span><span v-if="run.recommendedPlans.some((r:any)=>r.objectives.length>1)">同一路线同时最优时合并展示。</span></div><div v-if="combinations.length" class="combination-tags"><el-tag v-for="label in combinations" :key="String(label)" type="info" effect="plain">{{label}}</el-tag></div><p v-for="notice in run.recommendationUnavailable" :key="notice.objective" class="recommendation-notice">{{notice.message}}</p><div class="candidate-strip"><button v-for="c in candidates" :key="c.id" type="button" class="candidate-card" :class="{chosen:active?.id===c.id}" :aria-pressed="active?.id===c.id" @click="preview=c.id;segment=0"><div class="recommendation-label">{{c.recommendationLabel}}</div><div class="candidate-title"><small>整单总费用</small><strong>{{money(c.costCents)}}</strong></div><span class="candidate-unit-cost">折合 {{unitCost(c.costCents)}}</span><span class="candidate-route">{{c.name}}</span><span class="candidate-name">{{c.familyLabel||c.modes.map((m:string)=>modeNames[m]).join(' + ')}}</span><div><span>可靠性评分</span><b>{{c.reliability}} / 100</b></div><div><span>预计全程</span><b>{{hours(c.durationSeconds)}}</b></div><small>{{c.estimated?'费用估算':'参考报价'}} · {{c.scheduleComplete?'参考排程':'班期待确认'}}</small></button></div><el-collapse v-if="alternatives.length" class="alternative-plans"><el-collapse-item :title="'其他可行路线（'+alternatives.length+'）'"><button v-for="c in alternatives" :key="c.id" type="button" class="alternative-card" :class="{chosen:active?.id===c.id}" :aria-pressed="active?.id===c.id" @click="preview=c.id;segment=0"><span><b>{{c.familyLabel||c.modes.map((m:string)=>modeNames[m]).join(' + ')}}</b><small>{{c.name}}</small></span><span>{{unitCost(c.costCents)}}<small>{{hours(c.durationSeconds)}} · 可靠性 {{c.reliability}}</small></span></button></el-collapse-item></el-collapse>
<div class="active-summary"><span class="active-recommendation">{{activeRecommendation?.recommendationLabel||(active.familyLabel+'备选方案')}}</span><strong>{{active.name}}</strong><p v-for="reason in activeRecommendation?.recommendationReasons" :key="reason" class="recommendation-reason">{{reason}}</p><div><span>全程费用 {{money(active.costCents)}}</span><span>{{active.distanceComplete?(active.distanceMeters/1000).toFixed(0)+' km':'部分里程待核验'}}</span></div><small>测算到达 {{date(active.referenceArrivalAt)}} · 已计入预计候班和装卸</small></div>
<div class="segment-timeline"><article v-for="s in active.segments" :key="s.id" class="segment-stop" :class="{highlighted:segment===s.sequence}"><div class="stop-name"><i></i><strong>{{s.origin.name}}</strong></div><div class="segment-card" @click="segment=s.sequence"><div class="segment-mode" :class="s.mode.toLowerCase()"><span>{{s.mode==='ROAD'?'🚚':s.mode==='RAIL'?'🚆':'🚢'}}</span>{{modeNames[s.mode]}}</div><div class="segment-main"><div class="segment-metrics"><div><span>里程</span><b>{{s.distanceMeters?(s.distanceMeters/1000).toFixed(0)+' km':'待核验'}}</b></div><div><span>运输时效</span><b>{{hours(s.durationSeconds)}}</b></div><div><span>区段费用</span><b>{{unitCost(s.costCents)}}</b></div><div><span>可靠性评分</span><b>{{s.reliability}}</b></div></div><p>{{s.lineName||'公路接驳'}} · {{form.loadingType==='CONTAINER'?form.containerType:s.priceSnapshot.conversionRequired?(s.priceSnapshot.conversionCharged===false?'已入箱接续运输':'散粮入箱'):'散货'}}</p><div class="segment-footer"><small>衔接/作业 {{hours(s.waitSeconds)}} · {{s.priceSnapshot.estimated?'费用估算':'参考测算'}}</small><el-button link type="primary" @click.stop="detail=s;segment=s.sequence">费用 {{s.fees.length}} · 查看详情</el-button></div></div></div></article><div class="stop-name terminal"><i></i><strong>{{active.segments.at(-1)?.destination.name}}</strong></div></div>
<el-collapse class="plan-caveats"><el-collapse-item title="测算说明与待确认事项"><p>可靠性为模型评分：区段基础分均值 − 每次衔接2分。</p><p v-for="w in [...(run.warnings||[]),...active.warnings]" :key="w">{{w}}</p></el-collapse-item></el-collapse><div class="publish-actions"><p v-if="dirty">输入条件已修改，请重新求解后发布。</p><template v-else-if="run.publication"><el-tag type="success">已发布</el-tag><el-button type="primary" @click="router.push({path:'/matches',query:{id:run.publication.id}})">查看议价</el-button></template><span v-else-if="canPublish" class="supplier-next-step">在下方选择物流供应商后发布方案</span></div></template>
<el-empty v-else :description="run?'没有满足条件的方案，请调整总预算、到达时间或运输方式':'填写条件后求解，比较可靠性、成本和时效'" :image-size="95"/></aside></section>
<section v-if="run&&active" class="supplier-panel"><header class="supplier-heading"><div><h3>推荐物流供应商</h3><p>按当前方案筛选已发布运力，综合路线、报价、接单记录和企业注册地排序。</p></div><el-button :loading="supplierLoading" :disabled="publishing||solving" @click="loadSuppliers">刷新推荐</el-button></header>
<el-skeleton v-if="supplierLoading" :rows="4" animated/><el-alert v-else-if="supplierError" :title="supplierError" type="error" :closable="false"/><el-empty v-else-if="!supplierRows.length" description="暂无适配当前方案的已发布运力，请切换路线后重试" :image-size="70"/>
<el-checkbox-group v-else v-model="selectedSupplyIds" class="supplier-grid" aria-label="选择物流供应商" :disabled="dirty||solving||publishing||!!run.publication||!canPublish"><el-checkbox v-for="s in supplierRows" :key="s.supplyId" :value="s.supplyId" :aria-label="s.carrierName" class="supplier-card" :class="{selected:selectedSupplyIds.includes(s.supplyId)}"><div class="supplier-card-content"><header><strong>{{s.carrierName}}</strong><span class="supplier-score"><span>推荐值</span><strong>{{s.score}}<small> 分</small></strong></span></header><p class="supplier-route">{{s.origin}} → {{s.destination}}</p><div class="supplier-price"><strong>{{s.unitPriceCents==null?'待协商':money(s.unitPriceCents)+'/吨'}}</strong><small>整程参考 {{money(s.totalCents)}}</small></div><div class="supplier-facts"><span>路线匹配 <b>{{s.routeMatch}}%</b></span><span>已接单 <b>{{s.acceptedOrders}} 笔</b></span><span>注册地 <b>{{s.registeredRegion}}</b></span><span>承运范围 <b>{{Number(s.capacityMin).toFixed(1)}}–{{Number(s.capacityMax).toFixed(1)}} 吨</b></span></div><p>{{s.modeLabel}} · {{s.priceLabel}}</p><div class="supplier-reasons"><el-tag v-for="reason in s.reasons" :key="reason" size="small" effect="plain" type="info">{{reason}}</el-tag></div><small v-for="warning in s.warnings" :key="warning" class="supplier-warning">{{warning}}</small></div></el-checkbox></el-checkbox-group>
<footer class="supplier-actions"><span>{{run.publication?'方案已发布':selectedSuppliers.length?'已选择 '+selectedSuppliers.length+' 家物流供应商':'可多选物流供应商，发布后分别进行议价'}}<small>运力报价供比选，成交条款由双方议价确认。</small></span><el-button v-if="canPublish&&!run.publication" type="primary" :disabled="!selectedSuppliers.length||dirty||solving||supplierLoading" @click="showPublish">发布此方案</el-button><el-button v-else-if="run.publication" type="primary" @click="router.push({path:'/matches',query:{id:run.publication.id}})">查看议价</el-button></footer></section></div>
<el-dialog :model-value="!!detail" title="运输区段详情" width="min(860px, 95vw)" @close="detail=null"><template v-if="detail"><div class="detail-route"><el-tag>{{modeNames[detail.mode]}}</el-tag><strong>{{detail.origin.name}} → {{detail.destination.name}}</strong></div><el-descriptions class="detail-billing-basis" :column="2" border><el-descriptions-item label="货物数量">{{measure(run?.input?.quantity,1)}} 吨</el-descriptions-item><el-descriptions-item label="本段里程">{{detail.distanceMeters==null?'待确认':measure(detail.distanceMeters/1000,0,3)+' 公里'}}</el-descriptions-item></el-descriptions><h3>费用明细</h3><el-table :data="detail.fees"><el-table-column prop="name" label="费用项目" min-width="130"/><el-table-column label="单价" min-width="140"><template #default="{row}">{{row.rate==null?'—':Number(row.rate).toLocaleString('zh-CN',{maximumFractionDigits:3})}} {{row.unit}}</template></el-table-column><el-table-column label="计费量" min-width="240"><template #default="{row}"><span class="fee-quantity">{{feeQuantity(row)}} {{feeUnits[row.unit]||''}}</span><small v-if="feeBasis(row)" class="fee-calculation">{{feeBasis(row)}}</small></template></el-table-column><el-table-column label="区段金额" min-width="145"><template #default="{row}">{{money(row.costCents)}}</template></el-table-column></el-table><p class="detail-total">合计 {{money(detail.costCents)}} · {{detail.priceSnapshot.estimated?'费用估算，待承运商报价':'参考价格，待实际成交'}}</p><el-descriptions :column="2" border><el-descriptions-item label="参考运输时效">{{hours(detail.durationSeconds)}}</el-descriptions-item><el-descriptions-item label="衔接及作业时间">{{hours(detail.waitSeconds)}}</el-descriptions-item><el-descriptions-item label="可靠性">{{detail.reliability}}分 · 模型评分</el-descriptions-item><el-descriptions-item label="路径类型">{{detail.geometry?'高德公路路径 / 已核验几何':detail.displayPath?'运输走廊示意':'路径待补充'}}</el-descriptions-item><el-descriptions-item label="公开服务" :span="2">{{detail.priceSnapshot.service?.code||'公路接驳'}} · {{detail.priceSnapshot.service?.frequency||'按需安排'}} · {{detail.priceSnapshot.service?.transitLabel||'道路行驶与作业预计时长'}}</el-descriptions-item></el-descriptions><p class="detail-notes">{{detail.priceSnapshot.assumptions||'公路通用路径未校验货车限行；预计时效按每8小时行驶增加4小时休息测算，接驳作业另计。'}}费用以表列项目为范围，其他费用由后续整体承接报价明确。</p><a v-if="detail.priceSnapshot.service?.sourceUrl" :href="detail.priceSnapshot.service.sourceUrl" target="_blank" rel="noopener noreferrer">查看公开路线资料</a></template></el-dialog>
<el-dialog v-model="publishOpen" title="发布此方案" width="560px" :close-on-click-modal="!publishing" :show-close="!publishing" :close-on-press-escape="!publishing"><el-alert v-if="publishError" :title="publishError" type="error" :closable="false"><el-button link @click="publishOpen=false;loadSuppliers()">刷新供应商推荐</el-button></el-alert><p>{{Number(form.quantity).toFixed(1)}} 吨 · {{active?.familyLabel}}</p><div class="publish-supplier"><strong>已选择 {{selectedSuppliers.length}} 家物流供应商</strong><ul class="publish-supplier-list"><li v-for="s in selectedSuppliers" :key="s.supplyId">{{s.carrierName}}<span>推荐值 {{s.score}} 分</span></li></ul><p>{{active?.name}}</p><small>发布后由所选供应商分别报价，确认一家企业整体承运。</small></div><el-form label-position="top" :disabled="publishing"><template v-if="!run?.demandId"><el-form-item label="联系人" required><el-input v-model="publication.contact" maxlength="40" aria-label="联系人"/></el-form-item><el-form-item label="联系电话" required><el-input v-model="publication.phone" maxlength="30" aria-label="联系电话"/></el-form-item></template><el-form-item label="响应截止时间" required><el-date-picker v-model="publication.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="响应截止时间"/></el-form-item></el-form><template #footer><el-button :disabled="publishing" @click="publishOpen=false">取消</el-button><el-button type="primary" :loading="publishing" @click="publish">发布</el-button></template></el-dialog>
</template>
